SELECT * FROM attendance 
WHERE staff_id = #{staffId} AND sign_type = #{signType} 
AND sign_time BETWEEN #{startTime} AND #{endTime}
LIMIT 1

SELECT * FROM attendance 
WHERE staff_id = #{staffId}
AND sign_time BETWEEN #{startDate} AND #{endDate}
ORDER BY sign_time DESC

SELECT * FROM attendance 
WHERE location_status = #{locationStatus}
ORDER BY sign_time DESC

SELECT * FROM attendance 
WHERE 1=1

    AND location_status = #{locationStatus}


    AND sign_type = #{signType}


    AND (staff_no LIKE CONCAT('%', #{keyword}, '%') OR staff_name LIKE CONCAT('%', #{keyword}, '%'))


    AND DATE(sign_time) = #{date}

ORDER BY sign_time DESC
